using System;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public sealed class AvalancheSceneTests
{
 Component match;SerializedObject data;
 [OneTimeSetUp]public void Open(){EditorSceneManager.OpenScene("Assets/TruckAvalancheEscape/Scenes/TruckAvalancheEscape.unity");var type=Type.GetType("LWS.TruckAvalancheEscape.AvalancheMatch, Assembly-CSharp",true);match=Resources.FindObjectsOfTypeAll(type).Cast<Component>().First(c=>c.gameObject.scene.IsValid());data=new SerializedObject(match);}
 [Test]public void EveryAuthoredBehaviourAndSharedPresentationReferenceResolves(){foreach(var root in match.gameObject.scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))Assert.Zero(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject),t.name);foreach(string name in new[]{"drivingViews","broadcast","atmosphere","menus","feedback"})Assert.NotNull(data.FindProperty(name).objectReferenceValue,name);Assert.NotNull(AssetDatabase.LoadAssetAtPath<Sprite>("Assets/TruckSports/Art/Logos/TruckAvalancheEscape.png"));}
 [Test]public void TwelveStartsAreLevelSpacedAndAboveTheActualStagingSurface(){var world=new SerializedObject(data.FindProperty("world").objectReferenceValue);var starts=world.FindProperty("starts");Assert.AreEqual(12,starts.arraySize);Assert.AreEqual(12,data.FindProperty("trucks").arraySize);var deck=GameObject.Find("Broad flat safe mountain staging platform").GetComponent<Collider>();float top=deck.bounds.max.y;for(int i=0;i<12;i++){var p=starts.GetArrayElementAtIndex(i).vector3Value;Assert.AreEqual(top+.65f,p.y,.05f);for(int j=0;j<i;j++)Assert.Greater(Vector3.Distance(p,starts.GetArrayElementAtIndex(j).vector3Value),10);}}
 [Test]public void AvalancheAndRiskRoutesHaveActualPhysicsAndNoDynamicDebrisParentedToTheMovingFront(){var world=new SerializedObject(data.FindProperty("world").objectReferenceValue);Assert.GreaterOrEqual(world.FindProperty("routes").arraySize,3);var front=(Component)data.FindProperty("front").objectReferenceValue;var f=new SerializedObject(front);Assert.True(((BoxCollider)f.FindProperty("contact").objectReferenceValue).isTrigger);Assert.Greater(f.FindProperty("debris").arraySize,12);var debris=f.FindProperty("debris");for(int i=0;i<debris.arraySize;i++)Assert.False(((Rigidbody)debris.GetArrayElementAtIndex(i).objectReferenceValue).transform.IsChildOf(front.transform));}
 [Test]public void RollingDebrisUsesInstalledModelsWithoutAddingNestedPhysics(){var front=new SerializedObject(data.FindProperty("front").objectReferenceValue);var debris=front.FindProperty("debris");for(int i=0;i<debris.arraySize;i++){var body=(Rigidbody)debris.GetArrayElementAtIndex(i).objectReferenceValue;Assert.False(body.GetComponent<MeshRenderer>().enabled,body.name);Assert.NotNull(body.transform.Find("Installed avalanche debris artwork"));Assert.Greater(body.GetComponentsInChildren<MeshRenderer>().Count(r=>r.enabled),0);Assert.AreEqual(1,body.GetComponentsInChildren<Rigidbody>().Length);Assert.AreEqual(1,body.GetComponentsInChildren<Collider>().Length);}}
 [Test]public void TerrainCannotIntersectTheStagingDeckOrHideTheExistingRoads(){var world=new SerializedObject(data.FindProperty("world").objectReferenceValue);var terrain=(Terrain)world.FindProperty("terrain").objectReferenceValue;var starts=world.FindProperty("starts");for(int i=0;i<starts.arraySize;i++){var p=starts.GetArrayElementAtIndex(i).vector3Value;Assert.Less(terrain.SampleHeight(p)+terrain.transform.position.y,430f-.1f,"terrain intrusion at "+p);}var routes=world.FindProperty("routes");for(int i=0;i<routes.arraySize;i++){var points=routes.GetArrayElementAtIndex(i).FindPropertyRelative("points");for(int j=1;j<points.arraySize;j++)foreach(float t in new[]{.1f,.5f,.9f}){var p=Vector3.Lerp(points.GetArrayElementAtIndex(j-1).vector3Value,points.GetArrayElementAtIndex(j).vector3Value,t);Assert.Less(terrain.SampleHeight(p)+terrain.transform.position.y,p.y-.05f,"terrain hides existing route "+i+" at "+p);}}}
 [Test]public void ActualSolidRoadsCannotRiseThroughTheTwelveStartingTrucks(){Physics.SyncTransforms();var world=new SerializedObject(data.FindProperty("world").objectReferenceValue);var starts=world.FindProperty("starts");for(int i=0;i<starts.arraySize;i++){var p=starts.GetArrayElementAtIndex(i).vector3Value;var hits=Physics.RaycastAll(p+Vector3.up*10,Vector3.down,25,~0,QueryTriggerInteraction.Ignore).Where(h=>h.rigidbody==null&&h.normal.y>.8f).ToArray();Assert.Greater(hits.Length,0);Assert.AreEqual(430,hits.Max(h=>h.point.y),.025f,"spline overshoot at "+p);}}
 [Test]public void AIAdvancesAtItsActualOffsetWaypoint(){var component=(Component)data.FindProperty("world").objectReferenceValue;var world=new SerializedObject(component);var points=world.FindProperty("routes").GetArrayElementAtIndex(0).FindPropertyRelative("points");int index=10;var point=points.GetArrayElementAtIndex(index).vector3Value;var before=points.GetArrayElementAtIndex(index-1).vector3Value;var right=Vector3.Cross(Vector3.up,Vector3.ProjectOnPlane(point-before,Vector3.up).normalized);var actor=point+right*15;Assert.Greater(Vector3.Distance(actor,point),13);var method=component.GetType().GetMethod("Target");object[] args=method.GetParameters().Length==3?new object[]{0,actor,index}:new object[]{0,actor,index,15f};method.Invoke(component,args);Assert.AreEqual(index+1,(int)args[2],"A truck at its real15m-offset waypoint must advance even when outside the centreline13m radius.");}
 [Test]public void CliffTakeoffHasMatchingVisibleAndSolidCurvedGeometry(){var ramp=GameObject.Find("Actual curved cliff-gap takeoff ramp");Assert.NotNull(ramp);var mesh=ramp.GetComponent<MeshFilter>().sharedMesh;Assert.AreSame(mesh,ramp.GetComponent<MeshCollider>().sharedMesh);Assert.Greater(mesh.vertexCount,20);Assert.NotNull(ramp.GetComponent<Renderer>().sharedMaterial);Assert.Greater(mesh.bounds.max.y-mesh.bounds.min.y,1);}
 [Test]public void RouteCentresFollowActualRoadCollisionIncludingTheFrozenRiverBridge(){Physics.SyncTransforms();var roadType=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("LWS.InterstateHauler.LwsRoadSurface",false)).First(t=>t!=null);var world=new SerializedObject(data.FindProperty("world").objectReferenceValue);var routes=world.FindProperty("routes");for(int route=0;route<routes.arraySize;route++){var points=routes.GetArrayElementAtIndex(route).FindPropertyRelative("points");for(int i=1;i<points.arraySize;i++){var a=points.GetArrayElementAtIndex(i-1).vector3Value;var b=points.GetArrayElementAtIndex(i).vector3Value;for(float distance=10;distance<Vector3.Distance(a,b);distance+=20){var p=Vector3.Lerp(a,b,distance/Vector3.Distance(a,b));if(route==1&&p.z>575&&p.z<625)continue;var hits=Physics.RaycastAll(p+Vector3.up*3,Vector3.down,8,~0,QueryTriggerInteraction.Ignore);Assert.True(hits.Any(h=>h.rigidbody==null&&h.collider.GetComponent(roadType)!=null&&Mathf.Abs(h.point.y-p.y)<.08f),"road/bridge route mismatch "+route+" at "+p);}}}}

}
